final class AVAUpdateInventSumValuesController extends SysOperationServiceController
{
}

Method.Source:
public static AVAUpdateInventSumValuesController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVAUpdateInventSumValuesController controller;
    controller = new AVAUpdateInventSumValuesController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

public static void main(Args _args)
{
    AVAInventSumDateTrans       trans;
    AVAUpdateInventSumValuesController controller;
    AVAUpdateInventSumValuesContract   contract;

    if (_args.record() && _args.dataset() == tableNum(AVAInventSumDateTrans))
    {
        trans = _args.record();
    }
    controller = AVAUpdateInventSumValuesController::construct();
    contract = controller.getDataContractObject();
    if (trans)
    {
        contract.parmSumType(trans.Type);
        contract.parmInventLocationId(trans.InventLocationId);
        contract.parmInventSiteId(trans.InventSiteId);
        //controller.parmShowDialog(false);
    }
    controller.parmArgs(_args);
    controller.startOperation();
}
